// Extract data from AI Agent output
const agentOutput = $json.output || $json.text || '';
let classification = {};

try {
  // Try to parse JSON from agent output
  const jsonMatch = agentOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    classification = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // Use defaults if parsing fails
}

// Get original ticket data from validation
const ticketData = $('Validate JSON Schema').first().json;

return {
  json: {
    // Original ticket data
    ticket_id: ticketData.ticket_id || $json.ticket_id,
    subject: ticketData.subject || $json.subject,
    description: ticketData.description || $json.description,
    requester_email: ticketData.requester_email || $json.requester_email,
    requester_name: ticketData.requester_name || $json.requester_name,

    // AI classification results
    ai_category: classification.category || 'Needs Review',
    ai_priority: classification.priority || 'medium',
    ai_urgency: classification.urgency || 'medium',
    ai_confidence: classification.confidence || 0,
    ai_suggested_resolution: classification.suggested_resolution || 'Manual review required',

    // Metadata
    requires_human_review: true,
    classified_at: new Date().toISOString()
  }
};

const originalData = $('Confidence Threshold Check').first().json;
const slackResponse = $json;
return {
  json: {
    ...originalData,
    incident_number: originalData.incident_number || null,
    is_update: originalData.is_update || false,
    slack_response: slackResponse,
    human_review_sent: true
  }
};

const formData = $('ServiceNow Create or Update').first().json;
const lookupResult = $json;
return {
  json: {
    ...formData,
    lookup_sys_id: lookupResult.result?.[0]?.sys_id || null,
    lookup_result: lookupResult.result?.[0] || null
  }
};
